pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 value) public {
        vm.assume(value <= 1 ether);
        vm.deal(address(this), value);

        bool reverted = false;
        try c.lockInGuess{value: value}(hash) {
            // Success means the lock was placed
            // In reference C, this only happens when value == 1 ether
        } catch {
            reverted = true;
        }

        // General rule: if value < 1 ether, the call must revert
        // In reference C: require(msg.value == 1 ether) ensures this
        // In mutant: require(msg.value == 0.5 ether) allows value == 0.5 ether to pass, breaking the rule
        assertTrue(value < 1 ether ? reverted : true);
    }
}

