pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, bytes32 hash) public {
        vm.assume(sender != address(0));
        vm.deal(sender, 1 ether);
        vm.prank(sender);
        c.lockInGuess(hash);

        // After lockInGuess, we check a general property: the settle function should not transfer ether when answer == 0 and guess == answer (which is only possible if answer == 0 and guess == 0).
        // In the reference, if answer == 0, the condition `answer != 0 && guesses[msg.sender].guess == answer` is false, so no transfer.
        // In the mutant, if answer == 0, the condition `answer == 0 && guesses[msg.sender].guess == answer` is true only when guess == 0, causing a transfer.
        // The general rule: after lockInGuess with hash != 0, settle should never transfer 2 ether.
        // We check by calling settle and verifying the balance increase is 0 when hash != 0.
        vm.assume(hash != bytes32(0));
        uint256 balanceBefore = sender.balance;
        vm.prank(sender);
        c.settle();
        uint256 balanceAfter = sender.balance;
        assertTrue(balanceAfter == balanceBefore, "Ether should not be transferred when hash != 0");
    }
}

