// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, bytes32 guessHash, uint blockOffset) public {
        vm.assume(sender != address(0));
        vm.assume(blockOffset >= 1 && blockOffset <= 256);
        vm.deal(sender, 2 ether);
        vm.prank(sender);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Mine to the settlement block
        vm.roll(block.number + blockOffset);

        uint preBalance = address(sender).balance;
        vm.prank(sender);
        c.settle();
        uint postBalance = address(sender).balance;

        // The rule: transfer happens iff blockhash is non-zero and equals the guess
        bytes32 answer = blockhash(block.number - blockOffset + 1);
        bool shouldTransfer = (answer != 0 && answer == guessHash);
        if (shouldTransfer) {
            assertTrue(postBalance == preBalance + 2 ether);
        } else {
            assertTrue(postBalance == preBalance);
        }
    }
}

